astro.term:
---
import type { PageDataPage } from '@heopress/astro-kit';
import { safeUrl } from '@heopress/astro-kit';
import SeoHead from '@heopress/astro-kit/SeoHead.astro';
import ItemBody from '@heopress/astro-kit/ItemBody.astro';
import Tooltip from 'heopress:ext/heopress_glossary/tooltip';
interface Props { page: PageDataPage }
const { page } = Astro.props;
const { vm } = page;
const item = vm.item;
const source = typeof item?.fields.source_url === 'string' ? item.fields.source_url : '';
const sourceTitle = typeof item?.fields.source_title === 'string' && item.fields.source_title !== '' ? item.fields.source_title : source;
---
<html lang={vm.page.locale}>
<head>
<meta charset="utf-8">
<SeoHead page={page} />
</head>
<body class="heopress-glossary heopress-glossary-term">
<main>
<article>
<h1>{item?.title}</h1>
<Tooltip page={page} />
<ItemBody page={page} />
{source !== '' && <p class="heopress-glossary-source">Source: <a href={safeUrl(source)}>{sourceTitle}</a></p>}
</article>
</main>
</body>
</html>

astro.index:
---
import type { PageDataPage } from '@heopress/astro-kit';
import { safeUrl } from '@heopress/astro-kit';
import SeoHead from '@heopress/astro-kit/SeoHead.astro';
interface Props { page: PageDataPage }
const { page } = Astro.props;
const { vm } = page;
---
<html lang={vm.page.locale}>
<head>
<meta charset="utf-8">
<SeoHead page={page} />
</head>
<body class="heopress-glossary heopress-glossary-index">
<main>
<h1>{vm.route?.title}</h1>
{vm.list.length > 0 && <dl class="heopress-glossary-list">{vm.list.map((c) => <><dt><a href={safeUrl(c.url)}>{c.title}</a></dt>{c.excerpt !== '' && <dd>{c.excerpt}</dd>}</>)}</dl>}
{vm.pagination && <nav class="heopress-glossary-pages">{vm.pagination.prevUrl && <a href={safeUrl(vm.pagination.prevUrl)} rel="prev">Previous</a>}{vm.pagination.nextUrl && <a href={safeUrl(vm.pagination.nextUrl)} rel="next">Next</a>}</nav>}
</main>
</body>
</html>

tooltip.astro:
---
import type { PageDataPage } from '@heopress/astro-kit';
interface Props { page: PageDataPage }
const { page } = Astro.props;
const item = page.vm.item;
const definition = item && item.collection === 'heopress_glossary__terms' && typeof item.fields.excerpt === 'string' ? item.fields.excerpt.trim() : '';
---
{definition !== '' && <aside class="heopress-glossary-tooltip" role="note"><dfn>{item?.title}</dfn> <span>{definition}</span></aside>}
